package com.multitenanterp.payroll;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payroll/runs") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER','PAYROLL_EXECUTIVE')")
public class PayrollCalculationController{private final PayrollCalculationService service;public PayrollCalculationController(PayrollCalculationService service){this.service=service;}@PostMapping("/calculate") @ResponseStatus(HttpStatus.CREATED) public PayrollRun calculate(@Valid @RequestBody PayrollCalculationRequest request,Authentication authentication){return service.calculate(request.year(),request.month(),authentication.getName());}@GetMapping("/{year}/{month}") public PayrollRun get(@PathVariable int year,@PathVariable int month){return service.get(year,month);}}
